-- BrandDesk: a handshake before the ask (LOCKED by Sean 2026-10-31: "lock it"). canon-ve-front-of-house v8 and a playbook record.
-- Sean: "is this too heavy of an ask for people who don't even know us? Should we be focusing on inviting people to get their guide...
-- I feel like we need a handshake before we ask them to commit to $500 a month."
update public.knowledge_records
set body = body || jsonb_build_object(
  'handshake', 'A handshake before the ask (Sean, 2026-10-31). Three steps. 1. The handshake, free: business outreach''s first email gives them their page (We built a page for {business}) with the top things from their free restaurant check, no price. 2. The $11 Vegan Restaurant Guide: their free check, every fix in plain words, Or have us do it on each fix; the pitch page''s Not now offers it too. 3. The BrandDesk pitch (their personal guided page and the price) only to a business that has shown a sign: clicked their page link, claimed their listing, ran the free check, bought the Guide, tapped Have us do it or Talk to someone, or is on Sean''s warm list. Never a cold $500 ask. Outreach starts in the chapters with the biggest gaps on the pitch list and the most signs; every city stays off until Sean turns it on.',
  'pitch', 'The monthly check-ups get a presence-gap ranking (no logo, a dated or broken website, missing hours, one platform, no recent Google reviews). A business on Sean''s warm list or one that has shown a sign (see handshake) gets a personal guided page: what we found (their audit), their site mocked up on our template from their listing, the two-week plan, the price and Get started, sent from Sean, city by city, approved by Sean. Ad console wording until it is live: included the day it opens.',
  'prepared_audits', 'We need the audits anyway, so the work is done before we reach out: a quick audit on every food place in the background; a presence-gap ranking (those who have it together, such as Love Life Cafe, fall to the bottom); the full audit plus a person''s review and the we-would-do-this plan for the businesses that have shown a sign and Sean''s warm list (businesses who asked for this). The page says plainly "We looked at your business before we reached out", never dressed as an instant scan. Business outreach''s first emails carry the handshake (their page and their free check), never the BrandDesk price (changed 2026-10-31; nothing had been sent).'),
  version = 8,
  change_summary = 'v8 (Sean, 2026-10-31, "lock it"): a handshake before the ask. Free page and free check first, the $11 Vegan Restaurant Guide next, the BrandDesk pitch only after a sign or for the warm list.',
  updated_at = now()
where slug = 'canon-ve-front-of-house' and version = 7;

insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 've-front-of-house', 'vegans-explore', 'Logan', $pb$DECISION, 2026-10-31 (Sean: "lock it"). A handshake before the ask. Sean: "is this too heavy of an ask for people who don't even know us?... I feel like we need a handshake before we ask them to commit to $500 a month." The ladder: 1. free, their Directory page and the top things from their free restaurant check in business outreach's first email, no price; 2. the $11 Vegan Restaurant Guide (every fix, Or have us do it); 3. the BrandDesk pitch page only after a sign (clicked their link, claimed, ran the check, bought the Guide, Have us do it, Talk to someone) or for Sean's warm list. Outreach starts in the chapters with the biggest gaps and the most signs; every city stays off until Sean turns it on. Canon canon-ve-front-of-house v8 (handshake, pitch, prepared_audits).$pb$, 'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 've-front-of-house' and body like 'DECISION, 2026-10-31 (Sean: "lock it"). A handshake%');
